INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Sola Symposium: Focus on greater quality to achieve greater equality', 'sola-symposium-university-limerick', '<p>In December (2016), <a href="https://www.disability-federation.ie/sola/" target="_blank" rel="noopener noreferrer">Sola</a> held a national symposium at University of Limerick. It brought together voices from communities, organisations and business to discuss services for disabled people.</p>
<p>The symposium asked how organisations and individuals could move from providing a service to being of service. It was geared towards disability organisation managers, volunteers and frontline staff, funders of disability services, and professionals with expertise in the field of quality.</p>
<p>Opening the event, former education minister Jan O’Sullivan, TD, emphasised “the importance of the voice of those for whom a service is being provided, and ensuring the service is of use”.</p>
<p>“The late Martin Naughton fought for so long to change that culture of expecting people to take whatever is provided, rather than to have control over their own lives and being able to decide what is right for them,” she said.</p>
<p>She congratulated Sola’s partners for their collaboration and co-operation, and hoped she was “correct in interpreting what this symposium is about: that it’s about ensuring the person is at the centre of the service”.</p>
<p>At the event, activists, academics and industrialists discussed what ‘quality’ meant to them. This coming together reflected Sola’s triple-backing from a national community organisation, a third-level institution and a private company.</p>
<p>In looking at how ‘lean principles’ – widely used in business and manufacturing – can be adopted by the community and voluntary sector, Billy Stack of <a href="https://www.disability-federation.ie" target="_blank" rel="noopener noreferrer">Disability Federation of Ireland</a> reviewed research on “using lean principals to enhance transport services for persons with a disability”.</p>
<p>Examining how quality systems can help protect people’s rights, Deirdre Nally gave a presentation on the potential of quality systems to protect a persons’ rights as enshrined in the UN Convention on the Rights of Persons with a Disability.</p>
<p>Meanwhile, Stuart Lawlor of the <a href="https://www.ncbi.ie" target="_blank" rel="noopener noreferrer">National Council for the Blind</a> talked about the practical steps needed to implement a quality management system in a community-based organisation.</p>
<p>The symposium also heard about a new system called PQASSO (pronounced ‘Picasso’) which promotes 11 core competencies, the majority of which put the person using an organisation’s services at the centre of those services.</p>
<p>While the event was focused on improving services, attendees were wary of ‘service- orientated’ language. Regarding service-delivery in particular, there was some concern expressed about ‘language-creep’, whereby the lingo from the ‘top’ is adopted by those on the frontlines.</p>
<p><strong><em>Disclosure: </em></strong><em>Claire Gallery, an administrator at Sola, is chairperson of Changing Ireland Community Media CLG.</em></p>
<p><em><a href="https://www.flickr.com/photos/infomatique/26991259334/" target="_blank" rel="noopener noreferrer">Main photo</a>: <a href="https://www.flickr.com/photos/infomatique/" target="_blank" rel="noopener noreferrer">William Murphy</a>/<a href="https://www.flickr.com">Flickr</a> (<a href="https://creativecommons.org/licenses/by-sa/2.0/legalcode" target="_blank" rel="noopener noreferrer">CC BY-SA 2.0</a>)</em></p>', 'At Sola’s gathering of activists, academics and private sector actors, disability activists made sure their voices were heard loud and clear.', 'https://changingireland.ie/wp-content/uploads/2017/06/26991259334_dbc58557dc_b.jpg', 'University of Limerick campus', '[{"slug":"equality-rights","title":"Equality & Rights"}]', '[{"slug":"disabilities","title":"disabilities"},{"slug":"events","title":"events"},{"slug":"sola","title":"Sola"},{"slug":"university-of-limerick","title":"University of Limerick"}]', '', 115, 1, '2017-06-26T19:57:00Z', '2019-09-13T14:45:42Z', '2017-06-26T19:57:00Z')
