INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Superb equality resource idea from Monaghan County Council', 'superb-equality-resource-idea-from-monaghan-county-council', '<h2><span><a href="https://drive.google.com/file/d/0Bw2kPUIQq1MbLUF6dUxmYnNVdTA/view?usp=sharing">Compare how different your life would have been had you lived  in 1955</a></span></h2>
<h2><i>&#8211; </i><b><i><span>Monaghan County Council’s booklet takes an unique approach to demonstrating how people’s struggle for social justice and equality has reaped many rewards. Anyone in Ireland today would find it useful to give them perspective in the struggle for equality.</span></i></b></h2>
<table cellspacing="0" cellpadding="0">
<tbody>
<tr>
<td><a href="https://2.bp.blogspot.com/-InH5Q-3YzDU/VxDzT92A2nI/AAAAAAAABIM/MzVVkJLduCIyd2o9WRVW-JlZev06OyXmwCK4B/s1600/Iss%2B53-monaghan%2Bequality%2B2p%2Bscreenshot.png"><span><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2016/04/Iss-2B53-monaghan-2Bequality-2B2p-2Bscreenshot-1-300x212.png" width="320" height="226" border="0" /></span></a></td>
</tr>
<tr>
<td><a href="https://drive.google.com/file/d/0Bw2kPUIQq1MbLUF6dUxmYnNVdTA/view?usp=sharing"><span><i>Click here to download the 2 page spread!</i></span></a></td>
</tr>
</tbody>
</table>
<p><span>Last year’s marriage referendum shook people involved with Monaghan’s social inclusion efforts.</span><span> </span><br />
<span>The ‘Yes’ side won by the narrowest of margins, less than one percent, in Cavan-Monaghan and according to Bernie Bradley, social inclusion officer with Monaghan County Council, “If we weren’t a joint constituency, it wouldn’t have passed.”</span><br />
<span>Their response was to produce a beautiful booklet titled ‘A Tale of Two Counties’ which is fast becoming the go-to resource for community workers seeking to educate people about the nine grounds for unlawful discrimination.</span><br />
<span>Through photographs and personal testimony (three pages of which are reproduced here) the book simultaneously contrasts yet merges the differing fates of youngsters in 1955 and 2015. </span><br />
<span>The booklet demonstrates how the fight for equality has changed the lives of so many people. Only Travellers have an even harder time of it now when it comes to discrimination. </span><br />
<span>“The results of the referendum show that this initiative is particularly important in Monaghan,” said Bernie.</span><br />
<span>So striking is the imagery and layout that the hardest cynic could not deny the benefits of the long struggle for a more equal society.</span><br />
<span>Monaghan’s experience of exclusion in 1955 can be seen as reflective of wider Irish society then. To put it mildly, it wasn’t easy fit in if you were different and there are many people today who can testify to that.</span><br />
<span>The book was launched last June as part of Social Inclusion Week by, then Minister-of-State, Aodhán Ó Ríordáin.</span><br />
<span>Elsewhere in the country, it has been greeted as a ground-breaking resource for community workers.</span><br />
<span>As Bernie puts it, “The truth is, every day in Monaghan, Ireland and the rest of the world people are often treated differently because they are different. But Monaghan Social Inclusion Measures group, led by Monaghan County Council wants everyone to feel it’s okay to be different.”</span><br />
<span>This isn’t the last you’ll hear from Monaghan regarding the struggle for equality. </span></p>
<p><b><i><span>Copies of the booklet are available by contacting the community department of Monaghan County Council on 047-73720. E: gcostello@monaghancoco.ie or bbradley@monaghancoco.ie</span></i></b><br />
<b><i><br />
</i></b><b><i><span>&#8211; By Allen Meagher &amp; Ben Panter for &#8216;Changing Ireland&#8217;.</span></i></b></p>
<div><b><i> </i></b></div>', 'Compare how different your life would have been had you lived in 1955 – Monaghan County Council’s booklet takes an unique approach to demonstrating how people’s struggle for social justice and equality has reaped many rewards. Anyone in Ireland today would find it useful to give them perspective in the struggle for equality. Click here to', 'https://changingireland.ie/wp-content/uploads/2016/04/Iss-2B53-monaghan-2Bequality-2B2p-2Bscreenshot-1.png', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 121, 1, '2016-04-15T13:02:00Z', '2019-09-13T10:44:13Z', '2016-04-15T13:02:00Z')
