INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Students “Stand Up!” to homophobic bullying', 'students-stand-up-to-homophobic-bullying', '<p>&nbsp;</p>
<div><a href="https://1.bp.blogspot.com/-_TeYg0mBDWo/VlMofyjC4DI/AAAAAAAABFY/QTRmG-7Mhxw/s1600/BeLonG%2BTo%2BLaunch%2BLK%2B07.JPG.jpg"><img loading="lazy" decoding="async" src="https://1.bp.blogspot.com/-_TeYg0mBDWo/VlMofyjC4DI/AAAAAAAABFY/QTRmG-7Mhxw/s400/BeLonG%2BTo%2BLaunch%2BLK%2B07.JPG.jpg" width="400" height="267" border="0" /></a></div>
<div>
<p>by Mark Quinn</p>
<p>The 7<sup><span>th</span></sup> annual “Stand Up!” week was launched this morning in St Nessan’s Community College, Limerick by the Minister for Education and Skills Jan O’Sullivan.</p>
</div>
<p>&nbsp;</p>
<div>The campaign runs until Friday 27th November and aims to address homophobic and transphobic bullying in schools and youth services by encouraging friendship and a positive understanding of LGBT young people.</div>
<p>&nbsp;</p>
<div>“Stand Up!” provides teachers and youth workers with information and materials that helps them to engage in a positive way with the issues that LGBT young people face.</div>
<p>&nbsp;</p>
<div>Speaking at the launch, Minister O’Sullivan said that her department is deeply committed to tackling this type of bullying in schools:</div>
<p>&nbsp;</p>
<div>“I urge every post-primary school to take part in this important initiative. It continues to go from strength-to-strength each year and is a great campaign, with benefits for students and entire school communities.”</div>
<p>&nbsp;</p>
<div>
<table cellspacing="0" cellpadding="0" align="center">
<tbody>
<tr>
<td><a href="https://3.bp.blogspot.com/-WwRSKMrJqXA/VlMoLhOwM5I/AAAAAAAABFQ/-pSDFgLGh5M/s1600/BeLonG%2BTo%2BJan1.JPG.jpg"><img loading="lazy" decoding="async" src="https://3.bp.blogspot.com/-WwRSKMrJqXA/VlMoLhOwM5I/AAAAAAAABFQ/-pSDFgLGh5M/s320/BeLonG%2BTo%2BJan1.JPG.jpg" width="320" height="232" border="0" /></a></td>
</tr>
<tr>
<td><i>Photos: Alan Place Photograph</i></td>
</tr>
</tbody>
</table>
<p>The campaign is run by BeLonG To, Ireland’s national organisation for Lesbian, Gay, Bisexual and Transgender (LGBT) young people.</p>
</div>
<div></div>
<p>&nbsp;</p>
<div></div>
<div></div>
<p>&nbsp;</p>
<div>Moninne Griffith, executive director of BeLonG To, said that the recent change to the constitution recognising equal marriage rights for same sex couples is a cause for optimism. However, there is still much work to be done to embed that into a cultural change that young people notice in their everyday lives:</div>
<p>&nbsp;</p>
<div>“Even when you introduce marriage equality, homophobia and transphobia don’t just go away over-night. You have to keep working on it and investing in projects that tackle it and that’s what ‘Stand Up!’ does.</div>
<p>&nbsp;</p>', 'by Mark Quinn The 7th annual “Stand Up!” week was launched this morning in St Nessan’s Community College, Limerick by the Minister for Education and Skills Jan O’Sullivan. The campaign runs until Friday 27th November and aims to address homophobic and transphobic bullying in schools and youth services by encouraging friendship and a positive', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 124, 1, '2015-11-23T15:04:00Z', '2019-09-13T10:44:26Z', '2015-11-23T15:04:00Z')
