INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Ecoeye inspired by Tipperary’s community energy scheme', 'ecoeye-inspired-by-tipperarys-community-energy-scheme', '<p>     </p>
<h2><span lang="EN-GB">&#8211; Duncan Stewart sees groundswell build in face of &#8220;massive change”</span></h2>
<div><span lang="EN-GB"><span>RTE’s Ecoeye on Feb 4<sup>th</sup>showcased the work of an unique LCDP-supported community energy project in North Tipperary.</span></span></div>
<div><span lang="EN-GB"><span>Reflecting afterwards on this and a project he visited on Inis Mor, presenter Duncan Stewart said, “I believe we’re on the cusp of a massive change… it’s slow but it’s coming.&#8221;</span></span></div>
<p><span lang="EN-GB"><span>All credit to the people in Drombane and Upperchurch in Tipperary, as well as North Tipperary Leader Partnership, for setting the example and showing how it can be done. </span></span></p>
<div><span lang="EN-GB"><span>The programme is <a href="https://www.rte.ie/player/ie/show/10249649/">available to view for 3 weeks on the RTE Player</a>.</span></span></div>
<table align="center" cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://1.bp.blogspot.com/-5PLrFle0FI0/UvIyI-HETUI/AAAAAAAAA-0/8xPppSjXqZY/s1600/RTE+EcoeyeDrum+Upper+TEA+mtg+Feb+4,+2014+.png"><img loading="lazy" decoding="async" border="0" src="https://1.bp.blogspot.com/-5PLrFle0FI0/UvIyI-HETUI/AAAAAAAAA-0/8xPppSjXqZY/s1600/RTE+EcoeyeDrum+Upper+TEA+mtg+Feb+4,+2014+.png" height="221" width="400" /></a></td>
</tr>
<tr>
<td><span><i><span>RTE&#8217;s Ecoeye visited Drumbane-Upperchurch to see how the Tipperary Energy Agency worked. <br />Their work featured in a broadcast on Feb 4, 2014.</span></i></span></td>
</tr>
</tbody>
</table>
<div>
<div><span lang="EN-GB"><span>Duncan is optimistic about communities showing resilience in the face of climate change:&nbsp;</span></span></div>
</div>
<div>
<div><span lang="EN-GB"><span>“Each community needs champions and a committed team. On Aran, it’s a co-operative; in Drumbane and Upperchurch, it was the local energy team. The idea of community energy is beginning to catch on.</span></span></div>
</div>
<div><span lang="EN-GB"><span></span></span></div>
<p><a name=''more''></a><span>“Recently, 51 local newspapers around Ireland have initiated the nationwide ‘Get Involved’ competition*, their aim is to encourage communities to set up sustainable energy co-ops in each Irish town.</span></p>
<div><span lang="EN-GB"><span>&#8220;I believe we’re on the cusp of a massive change. There&#8217;s going to be a groundswell movement in every small little community across Europe. In Ireland, it’s slow but it’s coming where people will be saying ‘We want local energy, we want not to be using fossil fuel, we want to be able to reduce our energy demand and I think that movement is just about to start.”</span></span></div>
<table align="center" cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://2.bp.blogspot.com/-dXZJU0L8EOo/UvIy4PpxHyI/AAAAAAAAA-8/lZPb0qNo4Ac/s1600/RTE+EcoeyeDrum+Upper+Chair+Noel,+Feb+4,+2014+.png.png"><img loading="lazy" decoding="async" border="0" src="https://2.bp.blogspot.com/-dXZJU0L8EOo/UvIy4PpxHyI/AAAAAAAAA-8/lZPb0qNo4Ac/s1600/RTE+EcoeyeDrum+Upper+Chair+Noel,+Feb+4,+2014+.png.png" height="223" width="400" /></a></td>
</tr>
<tr>
<td><i>Noel Byrne of Drombane-Upperchurch with Duncan Stewart.</i></td>
</tr>
</tbody>
</table>
<div><span lang="EN-GB"><span><b>* For more information, contact the SEAI or your local newspaper. The Drombane Upperchurch project has <a href="https://www.facebook.com/DUenergy">its own Facebook page.</a></b></span></span><br /><span lang="EN-GB"><span><b>Also, read &#8216;Changing Ireland&#8217;s earlier reports:&nbsp;<i><span>https://changingireland.blogspot.ie/2013/10/retrofit-country-and-well-save-3billion.html</span></i></b></span></span><br /><span><b><i><br /></i></b></span></div>
<p></p>', '– Duncan Stewart sees groundswell build in face of “massive change” RTE’s Ecoeye on Feb 4thshowcased the work of an unique LCDP-supported community energy project in North Tipperary. Reflecting afterwards on this and a project he visited on Inis Mor, presenter Duncan Stewart said, “I believe we’re on the cusp of a massive change… it’s', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 138, 1, '2014-02-05T12:52:00Z', '2019-09-13T10:44:55Z', '2014-02-05T12:52:00Z')
