INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Affordable (€10) ‘Social Media for Change’ training in Cork on Jan 21st', 'affordable-e10-social-media-for-change-training-in-cork-on-jan-21st', '<p><a href="https://4.bp.blogspot.com/-ozEBiBuWmPY/UtVFQZ1vZ6I/AAAAAAAAA-I/xKsIMIIRqZg/s1600/Landline+phone.jpg"><img loading="lazy" decoding="async" border="0" height="190" src="https://4.bp.blogspot.com/-ozEBiBuWmPY/UtVFQZ1vZ6I/AAAAAAAAA-I/xKsIMIIRqZg/s320/Landline+phone.jpg" width="320" /></a><span>In 1994, Ballyphehane CDP&#8217;s office had a typewritter and a telephone to communicate with the outside world. Now everyone has a tablet and they can communicate with most members of the community without leaving the building (they do leave the building).&nbsp;</span><span>On Jan 21st, they&#8217;re hosting a seminar on using Social Media for Social Change and will look at how new&nbsp;</span><span>technologies can help us communicate, campaign and challenge in the 21<sup>st</sup>&nbsp;century.</span></p>
<div><o:p></o:p></div>
<div></div>
<p><span>The event is supported by Cork City Partnership, the Irish Examiner and RTE.&nbsp;</span><br /><span>Cost €10.</span></p>
<h4><span><span>CLICK THE &#8220;READ MORE&#8221; BUTTON BELOW FOR DETAILS&#8230;<a name=''more''></a></span></span></h4>
<div><a href="https://2.bp.blogspot.com/-ipXykIF79Ks/UtVEG_sGteI/AAAAAAAAA-A/Fdh-mDjaYnk/s1600/Jan+21+Cork+Social+media+day.jpg"><img loading="lazy" decoding="async" border="0" height="640" src="https://2.bp.blogspot.com/-ipXykIF79Ks/UtVEG_sGteI/AAAAAAAAA-A/Fdh-mDjaYnk/s640/Jan+21+Cork+Social+media+day.jpg" width="452" /></a></div>
<p><span><br /></span></p>', 'In 1994, Ballyphehane CDP’s office had a typewritter and a telephone to communicate with the outside world. Now everyone has a tablet and they can communicate with most members of the community without leaving the building (they do leave the building). On Jan 21st, they’re hosting a seminar on using Social Media for Social Change and', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 139, 1, '2014-01-14T14:10:00Z', '2019-09-13T10:43:31Z', '2014-01-14T14:10:00Z')
