INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Publication of Mid-Term Review imminent', 'publication-of-mid-term-review-imminent', '<p> </p>
<div><span lang="EN-GB">It has been confirmed that a much-anticipated report on the Local and Community Development Programme will be published shortly.</span></div>
<div><span lang="EN-GB">Clodagh McDonnell, Principal Officer with the Department of the Environment, Community and Local Government, stated: </span></div>
<div><span lang="EN-GB">“The Mid-Term Review of the Local and Community Development Programme has been finalised and its recommendations will be taken on board in shaping the new successor programme to the LCDP, subject to funding provision in the upcoming budget, and, mindful, as is usual, of the continuing need for budgetary restraint and discipline.</span></div>
<div><span lang="EN-GB">“The Mid-Term Review is currently in limited circulation among chief stakeholders, including those in the Community and Voluntary Sector. The intention is to publish it post-budget, after October 15<sup>th</sup>,” she said.</span></div>
<p></p>', 'It has been confirmed that a much-anticipated report on the Local and Community Development Programme will be published shortly. Clodagh McDonnell, Principal Officer with the Department of the Environment, Community and Local Government, stated: “The Mid-Term Review of the Local and Community Development Programme has been finalised and its recommendations will be taken on board', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 150, 1, '2013-10-15T11:36:00Z', '2013-10-15T11:36:00Z', '2013-10-15T11:36:00Z')
