INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Where do you read yours?', 'where-do-you-read-yours', '<p> </p>
<div>
<table align="center" cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://3.bp.blogspot.com/-ciwC5pLdayY/Ul0O3K3kzbI/AAAAAAAAA5g/vOzYonzkxVU/s1600/George+Clancy+reading+Changing+Ireland+(Summer+''13).jpg"><img loading="lazy" decoding="async" border="0" height="240" src="https://3.bp.blogspot.com/-ciwC5pLdayY/Ul0O3K3kzbI/AAAAAAAAA5g/vOzYonzkxVU/s320/George+Clancy+reading+Changing+Ireland+(Summer+''13).jpg" width="320" /></a></td>
</tr>
<tr>
<td>George Clancy reading Changing Ireland Issue 41 in Argentina.</td>
</tr>
</tbody>
</table>
<p>We&#8217;re looking for someone to beat international rugby referee George Clancy&#8217;s impressive submission&#8230; Recently, we asked readers to send in snaps of themselves reading &#8216;Changing Ireland&#8217; (print or online) in unusual places.</p>
<p>So far, we&#8217;ve seen &#8216;Changing Ireland&#8217; being read in a stadium in San Juan, Argentina (George), in the Dail (Minister of State Jan O&#8217;Sullivan) &nbsp;and at an awards ceremony in Cloughjordan, by President Higgins.</p>
<table align="center" cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://4.bp.blogspot.com/-wNZPbGiENBI/Ul0R38Zxx5I/AAAAAAAAA5s/AozSf5LMKFs/s1600/PresHigginsCI.png"><img decoding="async" border="0" src="https://4.bp.blogspot.com/-wNZPbGiENBI/Ul0R38Zxx5I/AAAAAAAAA5s/AozSf5LMKFs/s1600/PresHigginsCI.png" /></a></td>
</tr>
<tr>
<td>President Higgins holding the issue, and appearing in cartoon form on the front page.&nbsp;</td>
</tr>
</tbody>
</table>
</div>
<div><span>Whatever or where next??!! Email: editor@changingireland.ie<o:p></o:p></span></div>
<div><span>PS<o:p></o:p></span></div>
<p></p>', 'George Clancy reading Changing Ireland Issue 41 in Argentina. We’re looking for someone to beat international rugby referee George Clancy’s impressive submission… Recently, we asked readers to send in snaps of themselves reading ‘Changing Ireland’ (print or online) in unusual places. So far, we’ve seen ‘Changing Ireland’ being read in a stadium in San Juan,', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 151, 1, '2013-10-15T10:05:00Z', '2013-10-15T10:05:00Z', '2013-10-15T10:05:00Z')
